create or replace function private.set_media_provider(p_id uuid,p_provider text) returns void language plpgsql security definer set search_path='' as $$begin if p_provider is null or p_provider not in('cloudinary','supabase') then raise exception 'Invalid provider';end if;update private.images set provider=p_provider,format=case when p_provider='supabase' then case when kind='voice' then 'm4a' else 'jpg' end else format end where id=p_id and not ready and not published and not destroyed;if not found then raise exception 'Invalid upload';end if;end $$;
